using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static void Mage(){
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Count(c=>c.CardClass=="MAGE")==25&&all.Where(c=>c.CardClass=="MAGE").All(matchRules.Supports),"All 25 frozen Mage cards implemented");
  var g=MatchFixture();var units=Enumerable.Range(0,5).Select(n=>g.Summon(1,"VAN_CS2_182")).ToArray();Check(g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,units[2].Id)).Success,"Cone accepts enemy minion");Check(units.Where((u,n)=>n>=1&&n<=3).All(u=>u.Health==4&&u.Frozen)&&units.Where((u,n)=>n==0||n==4).All(u=>u.Health==5&&!u.Frozen),"Cone locks exactly source and two adjacent minions");
  g=MatchFixture();units=Enumerable.Range(0,3).Select(n=>g.Summon(1,"VAN_CS2_182")).ToArray();g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,units[0].Id));Check(units[0].Frozen&&units[1].Frozen&&!units[2].Frozen,"Cone at left edge hits only available neighbor");
  g=MatchFixture();units=Enumerable.Range(0,3).Select(n=>g.Summon(0,"VAN_CS2_182")).ToArray();g.Play(0,Hand(g,"EX1_275"),new MatchTarget(0,units[2].Id));Check(!units[0].Frozen&&units[1].Frozen&&units[2].Frozen,"Cone can target friendly right edge");
  g=MatchFixture();var shield=g.Summon(1,"VAN_CS2_182");shield.Shield=true;g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,shield.Id));Check(shield.Frozen&&!shield.Shield&&shield.Health==5,"Cone freezes divine shield target even with no damage");
  g=MatchFixture();units=Enumerable.Range(0,3).Select(n=>g.Summon(1,"VAN_CS2_182")).ToArray();units[0].Stealth=true;g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,units[1].Id));Check(units[0].Frozen&&units[0].Health==4,"Adjacent stealth does not block area hit");
  g=MatchFixture();var target=g.Summon(1,"VAN_CS2_182");target.Stealth=true;int h=Hand(g,"EX1_275");Check(!g.Play(0,h,new MatchTarget(1,target.Id)).Success&&g.Players[0].Mana==10&&g.Players[0].Hand.Count==1,"Targeted stealth rejected atomically");Check(!g.Play(0,h,new MatchTarget(1)).Success&&g.Players[0].Mana==10,"Cone rejects hero without spending");
  g=MatchFixture();g.Summon(0,"VAN_EX1_012");var golem=g.Summon(1,"VAN_EX1_556");g.Damage(new MatchTarget(1,golem.Id),1);g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,golem.Id));Check(g.Players[1].Board.Single().CardId=="VAN_skele21"&&!g.Players[1].Board.Single().Frozen,"Deathrattle replacement is outside cone target batch");
  g=MatchFixture();var wyrm=g.Summon(0,"VAN_NEW1_012");g.Play(0,Hand(g,"GAME_COIN"));Check(g.AttackValue(wyrm)==2,"Mana Wyrm triggers on Coin");g.Play(0,Hand(g,"CS2_182"));Check(g.AttackValue(wyrm)==2,"Mana Wyrm ignores minion play");g.EndTurn();g.Play(1,Hand(g,"CS1_130",1),new MatchTarget(0));Check(g.AttackValue(wyrm)==2,"Mana Wyrm ignores opponent spell");g.EndTurn();g.Silence(new MatchTarget(0,wyrm.Id));g.Play(0,Hand(g,"GAME_COIN"));Check(g.AttackValue(wyrm)==1,"Silence clears Wyrm buff and stops trigger");
  g=MatchFixture();var anton=g.Summon(0,"VAN_EX1_559");g.Play(0,Hand(g,"GAME_COIN"));Check(g.Players[0].Hand.Single().CardId=="VAN_CS2_029"&&g.Players[0].Hand.Single().Generated,"Antonidas generates a fresh Fireball for Coin");var original=g.Players[0].Hand.Single();g.Play(0,original.Id,new MatchTarget(1));Check(g.Players[0].Hand.Single().CardId=="VAN_CS2_029"&&g.Players[0].Hand.Single().Id!=original.Id&&g.Players[1].Health==24,"Generated Fireball itself generates another");g.Silence(new MatchTarget(0,anton.Id));g.Players[0].Mana=10;g.Play(0,g.Players[0].Hand.Single().Id,new MatchTarget(1));Check(g.Players[0].Hand.Count==0,"Silenced Antonidas stops generating");
  g=MatchFixture();g.Summon(0,"VAN_EX1_559");g.Summon(0,"VAN_EX1_559");for(int n=0;n<9;n++)Hand(g,"CS2_182");g.Play(0,Hand(g,"GAME_COIN"));Check(g.Players[0].Hand.Count==10&&g.Players[0].Hand.Count(c=>c.CardId=="VAN_CS2_029")==1,"Multiple Antonidas respect hand cap after cast frees one slot");var wire=JsonData.Serializer().Serialize(LanProtocol.View(g,1,"mage",1));Check(!wire.Contains("VAN_CS2_029"),"Generated Fireball identity remains absent from enemy private snapshot");
  g=MatchFixture();g.Play(0,Hand(g,"EX1_612"));Check(g.Players[0].FreeSecretThisTurn&&g.CardCost(0,g.Card("VAN_EX1_287"))==0&&g.CardCost(0,g.Card("VAN_CS2_029"))==4,"Kirin Tor discounts secrets only");g.Players[0].Mana=0;Check(g.Play(0,Hand(g,"EX1_287")).Success&&g.Players[0].SecretCount==1&&!g.Players[0].FreeSecretThisTurn,"Zero mana can cast discounted secret and consumes offer");Check(g.CardCost(0,g.Card("VAN_EX1_289"))==3,"Next secret returns to normal cost");
  g=MatchFixture();g.Play(0,Hand(g,"EX1_287"));g.Players[0].Mana=10;g.Play(0,Hand(g,"EX1_612"));h=Hand(g,"EX1_287");int mana=g.Players[0].Mana;Check(!g.Play(0,h).Success&&g.Players[0].FreeSecretThisTurn&&g.Players[0].Mana==mana,"Illegal duplicate secret preserves free offer and resources");g.Play(0,Hand(g,"CS1_130"),new MatchTarget(1));Check(g.Players[0].FreeSecretThisTurn,"Non-secret spell does not consume free offer");g.EndTurn();Check(!g.Players[0].FreeSecretThisTurn,"Unused Kirin Tor offer expires at end of turn");
  g=MatchFixture();g.Play(0,Hand(g,"EX1_612"));g.Players[0].Mana=10;g.Play(0,Hand(g,"EX1_612"));g.Play(0,Hand(g,"EX1_287"));Check(!g.Players[0].FreeSecretThisTurn&&g.CardCost(0,g.Card("VAN_EX1_289"))==3,"Repeated Kirin Tor battlecries refresh but do not stack offers");
  g=MatchFixture();g.Summon(1,"VAN_EX1_616");g.Play(0,Hand(g,"EX1_612"));Check(g.CardCost(0,g.Card("VAN_EX1_287"))==0,"Kirin Tor overrides Loatheb-style spell cost aura");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,0,"mage",1)));Check(view.Players[0].FreeSecretThisTurn&&view.CardCost(0,view.Card("VAN_EX1_287"))==0,"Free secret offer survives explicit public snapshot");
  g=MatchFixture("MAGE","MAGE");g.Play(0,Hand(g,"EX1_287"));g.EndTurn();g.Players[1].Hand.Clear();wyrm=g.Summon(1,"VAN_NEW1_012");g.Summon(1,"VAN_EX1_559");g.Players[1].Mana=10;g.Play(1,Hand(g,"EX1_612",1));g.Play(1,Hand(g,"EX1_289",1));Check(g.Players[1].SecretCount==0&&!g.Players[1].FreeSecretThisTurn&&g.AttackValue(wyrm)==2&&g.Players[1].Hand.Single().CardId=="VAN_CS2_029","Countered free secret consumes offer and still triggers own spell-cast listeners");
  g=MatchFixture();g.Play(0,Hand(g,"EX1_612"));var kirinBody=g.Players[0].Board.Single();g.Silence(new MatchTarget(0,kirinBody.Id));Check(g.Players[0].FreeSecretThisTurn,"Silencing Kirin does not undo resolved battlecry");
  g=MatchFixture();g.Summon(0,"VAN_EX1_608");g.Summon(0,"VAN_EX1_608");g.Play(0,Hand(g,"EX1_612"));g.Play(0,Hand(g,"EX1_287"));Check(g.CardCost(0,g.Card("VAN_EX1_289"))==1,"After free offer consumption normal Apprentice auras remain");
  g=MatchFixture();var immuneNeighbor=g.Summon(1,"VAN_NEW1_023");target=g.Summon(1,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,target.Id));Check(immuneNeighbor.Frozen&&immuneNeighbor.Health==1,"Cone area hits ability-untargetable neighbor");
  g=MatchFixture();g.Summon(0,"VAN_EX1_350");g.Summon(0,"VAN_EX1_012");target=g.Summon(1,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_275"),new MatchTarget(1,target.Id));Check(target.Health==1&&target.Frozen,"Cone respects additive spell power then Velen doubling");
  var folder=Path.Combine(Environment.CurrentDirectory,"previews");Directory.CreateDirectory(folder);JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=all.Count(matchRules.Supports),TotalCards=all.Count,Cards=all.Select(c=>new{Id=c.Id,Name=c.Name,Supported=matchRules.Supports(c)}).ToArray(),Scope="All classic cards; Mage 25/25"});
 }
}
